            return $this->bar; // works, captures $this
        };
        $staticClosure = static function() {
            return $this->bar; // Error: "Using $this when not in object context"
        };
    }
}
```

So the statement "A closure declared as static function () {} does not capture $this" is TRUE.

Answer: "yes"

